259: pub enum RowAddrTranslator {
260:     Sync(Arc<RowAddrRemap>),
261:     Batch(Arc<dyn BatchRowIdRemapper>),
262: }
334:     pub async fn remap_row_addrs(&self, addrs: &[u64]) -> Result<Vec<Option<u64>>> {
335:         match self {
336:             Self::Sync(remap) => Ok(addrs
337:                 .iter()
338:                 .map(|&addr| remap.get(addr).unwrap_or(Some(addr)))
339:                 .collect()),
340:             Self::Batch(remapper) => remap_row_ids_async(*remapper, addrs).await,
341:         }
342:     }
343: 
344:     /// A synchronous map covering exactly `addrs`, so an existing synchronous
345:     /// remap step runs unchanged over one unit of work. `Sync` borrows its
346:     /// map; `Batch` translates `addrs` (deduplicated) and builds a map of
347:     /// that size, released with the returned value: memory is O(one unit),
348:     /// never O(source rows).
349:     pub async fn resolve(
350:         &self,
351:         addrs: impl IntoIterator<Item = u64>,
352:     ) -> Result<Cow<'a, RowAddrRemap>> {
353:         match self {
354:             Self::Sync(remap) => Ok(Cow::Borrowed(remap)),
355:             Self::Batch(remapper) => {
356:                 let mut addrs: Vec<u64> = addrs.into_iter().collect();
357:                 addrs.sort_unstable();
358:                 addrs.dedup();
359:                 let translated = remap_row_ids_async(*remapper, &addrs).await?;
360:                 let map: HashMap<u64, Option<u64>> = addrs.into_iter().zip(translated).collect();
361:                 Ok(Cow::Owned(RowAddrRemap::direct(map)))
362:             }

5201: fn visit_managed_row(
5202:     field: &LanceField,
5203:     array: &dyn Array,
5204:     row: usize,
5205:     visit: &mut impl FnMut(u32, Option<u32>, &str, Range<u64>) -> Result<()>,
5206: ) -> Result<()> {
5207:     if array.is_null(row) {
5208:         return Ok(());
5209:     }
5210:     if field.is_blob_v2() {
5211:         let values = array.as_struct_opt().ok_or_else(|| {
5212:             Error::internal("Expected Blob descriptor array during reference scan")
5213:         })?;
5214:         let columns = BlobV2DescriptorColumns::new(values);
5215:         if !columns.is_null_blob(row)
5216:             && matches!(
5217:                 BlobKind::try_from(columns.kinds.value(row))?,
5218:                 BlobKind::Managed | BlobKind::ManagedWithBase
5219:             )
5220:         {
5221:             let uri = columns.blob_uris.value(row);
5222:             lance_core::utils::blob::validate_managed_reference(
5223:                 uri,
5224:                 columns.positions.value(row),
5225:                 columns.sizes.value(row),
5226:             )?;
5227:             visit(
5228:                 field.id as u32,
5229:                 columns.managed_base_id(row),
5230:                 uri,
5231:                 columns.positions.value(row)
5232:                     ..columns.positions.value(row) + columns.sizes.value(row),
5233:             )?;
5234:         }
5235:         return Ok(());
5236:     }
5237:     match array.data_type() {
5238:         ArrowDataType::Struct(_) => {
5239:             for child in field
5240:                 .children
5241:                 .iter()
5242:                 .filter(|child| field_contains_blob(child))
5243:             {
5244:                 let values = array
5245:                     .as_struct()
5246:                     .column_by_name(&child.name)
5247:                     .ok_or_else(|| Error::internal("Missing Blob child during reference scan"))?;
5248:                 visit_managed_row(child, values.as_ref(), row, visit)?;
5249:             }
5250:         }
5251:         ArrowDataType::List(_) => {
5252:             let values = array.as_list::<i32>();
5253:             let child = field
5254:                 .children
5255:                 .first()
5256:                 .ok_or_else(|| Error::internal("Missing Blob list item field"))?;
5257:             for index in values.value_offsets()[row]..values.value_offsets()[row + 1] {
5258:                 visit_managed_row(child, values.values().as_ref(), index as usize, visit)?;
5259:             }
5260:         }
5261:         ArrowDataType::LargeList(_) => {
5262:             let values = array.as_list::<i64>();
5263:             let child = field
5264:                 .children
5265:                 .first()
5266:                 .ok_or_else(|| Error::internal("Missing Blob list item field"))?;
5267:             for index in values.value_offsets()[row]..values.value_offsets()[row + 1] {
5268:                 visit_managed_row(child, values.values().as_ref(), index as usize, visit)?;
5269:             }
5270:         }
5271:         _ => {
5272:             return Err(Error::not_supported(format!(
5273:                 "Cannot scan Managed references in {}",
5274:                 array.data_type()
5275:             )));
5276:         }
5277:     }
5278:     Ok(())
5279: }
5351: pub(super) async fn preserve_managed_descriptors(
5352:     dataset: &Arc<Dataset>,
5353:     field_id: u32,
5354:     values: &StructArray,
5355:     row_addrs: &[u64],
5356:     field: &ArrowField,
5357: ) -> Result<ArrayRef> {
5358:     if values.len() != row_addrs.len() {
5359:         return Err(Error::internal(
5360:             "Blob descriptors and row addresses have different lengths",
5361:         ));
5362:     }
5363:     let columns = BlobV2DescriptorColumns::new(values);
5364:     let mut builder = BlobDescriptorArrayBuilder::new_with_metadata(
5365:         field.name(),
5366:         field.is_nullable(),
5367:         field.metadata().clone(),
5368:     );
5369:     let mut context = BlobV2ReadContext::new(dataset, field_id);
5370:     for (row, row_addr) in row_addrs.iter().enumerate() {
5371:         if columns.is_null_blob(row) {
5372:             builder.push_null()?;
5373:             continue;
5374:         }
5375:         let kind = BlobKind::try_from(columns.kinds.value(row))?;
5376:         match kind {
5377:             BlobKind::Managed | BlobKind::ManagedWithBase => {
5378:                 context.collect_managed(&columns, row, *row_addr).await?;
5379:                 builder.push(BlobDescriptor::Managed {
5380:                     base_id: resolve_managed_base_id(
5381:                         dataset,
5382:                         field_id,
5383:                         *row_addr,
5384:                         columns.managed_base_id(row),
5385:                     )?,
5386:                     uri: columns.blob_uris.value(row).to_string(),
5387:                     offset: columns.positions.value(row),
5388:                     size: columns.sizes.value(row),
5389:                 })?;
5390:             }
5391:             BlobKind::Packed | BlobKind::Dedicated => {
5392:                 let location = context.blob_read_location(*row_addr).await?;
5393:                 let root = dataset.blob_base_path(location.base_id)?;
5394:                 let path = blob_path(
5395:                     &location.data_file_dir,
5396:                     &location.data_file_key,
5397:                     columns.blob_ids.value(row),
5398:                 );
5399:                 let uri = path
5400:                     .prefix_match(&root)
5401:                     .ok_or_else(|| {
5402:                         Error::internal(format!("Blob source {path} is outside base {root}"))
5403:                     })?
5404:                     .map(|part| part.as_ref().to_string())
5405:                     .collect::<Vec<_>>()
5406:                     .join("/");
5407:                 builder.push(BlobDescriptor::Managed {
5408:                     base_id: location.base_id,
5409:                     uri,
5410:                     offset: if kind == BlobKind::Dedicated {
5411:                         0
5412:                     } else {
5413:                         columns.positions.value(row)
5414:                     },
5415:                     size: columns.sizes.value(row),
5416:                 })?;
5417:             }
5418:             BlobKind::External => builder.push(BlobDescriptor::External {
5419:                 base_id: columns.blob_ids.value(row),
5420:                 uri: columns.blob_uris.value(row).to_string(),
5421:                 offset: columns.positions.value(row),
5422:                 size: columns.sizes.value(row),
5423:             })?,
5424:             BlobKind::Inline => {
5425:                 let file = context.collect_inline(&columns, row, *row_addr).await?;
5426:                 builder.push_inline(file.read().await?)?;
5427:             }
5428:         }
5429:     }
5430:     Ok(builder.finish()?.into_parts().1)
5431: }

