608: ) -> Result<InterleaveResult> {
609:     let total_rows: usize = part_id_columns.iter().map(|a| a.len()).sum();
610: 
611:     // Partition ids are bounded by `num_partitions`, so counting sort orders the
612:     // rows in O(n + num_partitions) passes instead of sorting n key tuples.
613:     let mut partition_counts = vec![0u64; num_partitions];
614:     for (batch_idx, col) in part_id_columns.iter().enumerate() {
615:         for row_idx in 0..col.len() {
616:             if col.is_null(row_idx) {
617:                 return Err(Error::invalid_input(format!(
618:                     "null partition ID at batch {} row {}",
619:                     batch_idx, row_idx
620:                 )));
621:             }
622:             let part_id = col.value(row_idx) as usize;
623:             if part_id >= num_partitions {
624:                 return Err(Error::invalid_input(format!(
625:                     "partition ID {} is out of range [0, {})",
626:                     part_id, num_partitions
627:                 )));
628:             }
629:             partition_counts[part_id] += 1;
630:         }
631:     }
632: 
633:     // Prefix sums turn the counts into the first slot of each partition's run,
634:     // then the scatter pass below consumes them as a write cursor per partition.
635:     let mut cursors = Vec::with_capacity(num_partitions);
636:     let mut running = 0usize;
637:     for &count in partition_counts.iter() {
638:         cursors.push(running);
639:         running += count as usize;
640:     }
641: 
642:     let mut interleave_indices = vec![(0usize, 0usize); total_rows];
643:     for (batch_idx, col) in part_id_columns.iter().enumerate() {
644:         for (row_idx, &part_id) in col.values().iter().enumerate() {
645:             let cursor = &mut cursors[part_id as usize];
646:             interleave_indices[*cursor] = (batch_idx, row_idx);
647:             *cursor += 1;
648:         }
649:     }
650: 
651:     Ok((interleave_indices, partition_counts))
