650:     /// Choose an unused exact base ID without reserving zero or overflowing at
651:     /// `u32::MAX`. The caller must publish the binding with its references and
652:     /// reject a concurrent attempt to bind the chosen ID to another location.
653:     pub fn unused_id(bases: impl IntoIterator<Item = u32>) -> Result<u32> {
654:         let mut ids = bases.into_iter().collect::<Vec<_>>();
655:         ids.sort_unstable();
656:         ids.dedup();
657:         let mut candidate = 0u32;
658:         for id in ids {
