343:                             || packed_position_col.is_null(i)
344:                             || blob_size_col.is_null(i)
345:                         {
346:                             return Err(Error::invalid_input(format!(
347:                                 "Managed blob row {i} requires URI, position, and size, plus a base ID for an explicit base"
348:                             )));
349:                         }
350:                         let uri = uri_col.value(i);
351:                         let position = packed_position_col.value(i);
352:                         let size = blob_size_col.value(i);
